	}

	// 申请编号已成功使用，日期与集合相同（顺序无关）：可以取回原清册，
	// 不因档案已销毁而判为受阻。
	report, err := s.Check(CheckRequest{
		ApplicationID: "APP-1",
		ProcessedOn:   MustParseDate("2025-01-10"),
		ArchiveIDs:    []string{"A-2", "A-1"},
	})
